// booking.js
// Small wrapper to send bookings to your real API.
// Configure the API base URL with REACT_APP_API_BASE in your environment (or window.__API_BASE__ at runtime).

const getApiBase = () => {
  // Prefer explicit env var, then runtime override, then default to same-origin
  if (process.env.REACT_APP_API_BASE) return process.env.REACT_APP_API_BASE.replace(/\/$/, '');
  if (typeof window !== 'undefined' && window.__API_BASE__) return window.__API_BASE__.replace(/\/$/, '');
  return '';
};

export async function createBooking(payload) {
  const base = getApiBase();
  const url = (base ? base : '') + '/api/bookings';
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      // include credentials so cookies (admin session) work when frontend runs on a different origin
      credentials: 'include',
      body: JSON.stringify(payload),
    });
    // handle no-content responses gracefully
    const text = await res.text();
    const json = text ? JSON.parse(text) : {};
    if (!res.ok) {
      return { success: false, error: json.error || 'Server error', status: res.status };
    }
    return { success: true, data: json };
  } catch (err) {
    return { success: false, error: err.message || 'Network error' };
  }
}

export async function getAvailability(date) {
  const base = getApiBase();
  const url = (base ? base : '') + '/api/availability?date=' + encodeURIComponent(date);
  try {
    const res = await fetch(url, { headers: { Accept: 'application/json' }, credentials: 'include' });
    if (!res.ok) return { success: false, error: 'Failed to fetch availability', status: res.status };
    const json = await res.json();
    return { success: true, data: json };
  } catch (err) {
    return { success: false, error: err.message || 'Network error' };
  }
}

